-- Generated by NewPlanets/gen_hoth_rancor.py.
-- Rimeclaw, the Glacial Rancor: Hoth world boss (Infinity's spiked exotic rancor). Mirrors AcklayWorldBossLoot: the engine respawns it,
-- WorldBossLootManager gives every eligible player their own rewards (plus the Hoth bonus roll).
local TAG = "[HOTH-RANCOR-WB]"
local function logf(fmt, ...)
	local s = string.format(TAG .. " " .. fmt, ...)
	if printLuaError then printLuaError(s) else print(s) end
end

local WorldBossLootManager = require("screenplays.managers.world_boss_loot_manager")

HothGlacialRancorWorldBoss = ScreenPlay:new {
	numberOfActs = 1,
	screenplayName = "HothGlacialRancorWorldBoss",

	planet = "hoth",
	x = 600.0, y = -4600.0, z = 10.0, heading = 200,

	bossTemplate = "hoth_glacial_rancor",
	bossName = "Rimeclaw, the Glacial Rancor",
	leashRadius = 120,
	respawnSeconds = 86400, -- 24 hours, like the other world bosses

	bootGuardKey = "HothGlacialRancorWorldBoss:booted:v1",
	FIRST_BROADCAST_DELAY = 240,
	REPEAT_EVERY_SECONDS = 10800,
	DATA_BOSS_OID = "HothGlacialRancorWorldBoss:bossOID",
	DATA_NEXT_BCAST_AT = "HothGlacialRancorWorldBoss:nextBcastAt",
	DATA_LOOP_STARTED = "HothGlacialRancorWorldBoss:loopStarted",

	-- WorldBossLootManager: 3 items per player, each from a randomly chosen collection (lootChance is ignored)
	lootGroups = {
		{
			groups = {
				{group = "krayt_tissue_rare", chance = 3000000},
				{group = "color_crystals", chance = 2000000},
				{group = "power_crystals", chance = 2000000},
				{group = "armor_attachments", chance = 1500000},
				{group = "clothing_attachments", chance = 1500000}
			},
			lootChance = 10000000
		},
		{ groups = { {group = "krayt_pearls", chance = 10000000} }, lootChance = 5000000 },
		{ groups = { {group = "house_deeds", chance = 10000000} }, lootChance = 2000000 },
		{ groups = { {group = "endgame_weapon_schematics", chance = 10000000} }, lootChance = 1500000 },
		{ groups = { {group = "bg_token_group", chance = 10000000} }, lootChance = 350000 }
	},

	bossPtr = nil
}

registerScreenPlay("HothGlacialRancorWorldBoss", true)

local function getFlag(k) return (readData and (tonumber(readData(k)) or 0) or 0) end
local function setFlag(k, v) if writeData then writeData(k, v) end end

local function galaxyBroadcast(msg, ctx)
	if type(broadcastToGalaxy) ~= "function" then return false end
	if ctx and pcall(broadcastToGalaxy, ctx, msg) then return true end
	if pcall(broadcastToGalaxy, nil, msg) then return true end
	return pcall(broadcastToGalaxy, msg)
end

function HothGlacialRancorWorldBoss:start()
	if not isZoneEnabled(self.planet) then return end
	if getFlag(self.bootGuardKey) == 1 then
		logf("start(): already booted; skipping duplicate")
		return
	end
	setFlag(self.bootGuardKey, 1)
	self:spawnBoss()
	if getFlag(self.DATA_LOOP_STARTED) ~= 1 then
		setFlag(self.DATA_LOOP_STARTED, 1)
		createEvent(5000, "HothGlacialRancorWorldBoss", "broadcastLoop", nil, "")
	end
end

function HothGlacialRancorWorldBoss:spawnBoss()
	local pBoss = spawnMobile(self.planet, self.bossTemplate, self.respawnSeconds, self.x, self.z, self.y, self.heading, 0)
	if pBoss == nil then
		logf("FATAL: spawnMobile failed")
		return
	end
	local boss = LuaCreatureObject(pBoss)
	if boss and boss.setHomeLocation then
		boss:setHomeLocation(self.x, self.z, self.y, self.leashRadius)
	end
	createObserver(DAMAGERECEIVED, "HothGlacialRancorWorldBoss", "onBossDamaged", pBoss)
	createObserver(OBJECTDESTRUCTION, "HothGlacialRancorWorldBoss", "onBossDeath", pBoss)
	self.bossPtr = pBoss
	setFlag(self.DATA_BOSS_OID, SceneObject(pBoss):getObjectID())
	setFlag(self.DATA_NEXT_BCAST_AT, os.time() + self.FIRST_BROADCAST_DELAY)
	logf("SPAWNED at (%.1f, %.1f, %.1f)", self.x, self.z, self.y)
end

function HothGlacialRancorWorldBoss:onBossDamaged(pBoss, pAttacker, _damage)
	if pBoss == nil or pAttacker == nil then return 0 end
	WorldBossLootManager:trackDamage(pBoss, pAttacker)
	return 0
end

function HothGlacialRancorWorldBoss:onBossDeath(pBoss, pKiller)
	if pBoss == nil then return 0 end
	WorldBossLootManager:onBossDeath(pBoss, self.lootGroups, self.bossName)
	setFlag(self.DATA_NEXT_BCAST_AT, os.time() + self.respawnSeconds + self.FIRST_BROADCAST_DELAY)
	if broadcastMessage then
		broadcastMessage("\\#00FF00" .. self.bossName .. " has been slain on Hoth!")
	end
	return 0
end

function HothGlacialRancorWorldBoss:broadcastLoop()
	if not self.bossPtr then
		local oid = tonumber(readData(self.DATA_BOSS_OID) or 0) or 0
		if oid > 0 then self.bossPtr = getSceneObject(oid) end
	end
	local nextBcast = tonumber(readData(self.DATA_NEXT_BCAST_AT) or 0) or 0
	if self.bossPtr and nextBcast > 0 and os.time() >= nextBcast then
		local alive = false
		pcall(function() alive = not CreatureObject(self.bossPtr):isDead() end)
		if alive then
			galaxyBroadcast(string.format("[NOTICE] %s stalks the southern ice plains of Hoth (%.0f, %.0f).",
				self.bossName, self.x, self.y), self.bossPtr)
		end
		setFlag(self.DATA_NEXT_BCAST_AT, os.time() + self.REPEAT_EVERY_SECONDS)
	end
	createEvent(5000, "HothGlacialRancorWorldBoss", "broadcastLoop", nil, "")
	return 0
end
